// ---------------------------------------------------------------- app detail

type AppDetailData struct {
	// Projects are the team's, for the settings' move; empty leaves the
	// section out.
	Projects []app.Project
	// Stages says saving waits for Deploy, so the settings say "Save"
	// rather than promise a rollout that does not happen until then.
	Stages bool
	// RefTargets are the other apps a variable can refer to, for the
	// variables tab's picker; empty leaves the picker out.
	RefTargets []app.ReferenceTarget
	// Vars is the rest of the variables tab: what is staged, what the
	// platform adds, and which of its controls the service supports.
	Vars VariablesView
	// CLI is what the product's CLI is called, for an empty service's
	// directions.
	CLI string
	// Bucket is a bucket's own: what it holds, and where it is reached. Nil
	// for every other service.
	Bucket *app.Bucket
	// VersionCheck says the Deployments tab asks, after it draws, what
	// version the database runs and what it is without. See
	// database_release.go.
	VersionCheck bool
	App          app.App
	Siblings     []app.App
	Tab          string
	Pods         []orchestrator.PodInfo
	Deployments  []app.Deployment
	BaseURL      string

	// Net is the app's routing. Loaded alongside the rest rather than on its
	// own page: a panel nothing links to is a panel nobody finds, which is
	// exactly what happened the first time.
	Net app.Networking

	// ResolverName is which resolver answered the last domain check, so the
	// page can attribute what it reports rather than stating it as fact.
	ResolverName string

	// The resource tracks, with ceilings taken from the cluster's largest
	// node — what a single pod can actually be scheduled onto.
	CPULimit      ResourceSlider
	MemoryLimit   ResourceSlider
	CPURequest    ResourceSlider
	MemoryRequest ResourceSlider

	// RepoError is why the connected repository could not be read, shown on
	// the source card. A private repo, a typo and an outage all land here.
	RepoError string

	Notice string

	// Error is a refusal from the action that produced this render, shown with
	// the form that caused it rather than carried through a redirect.
	Error string

	// Deploy on push. HooksOn is whether the section is offered at all: a Git
	// app on an install with the webhook surface mounted.
	HooksOn bool
	Hook    app.Hook
	HookURL string

	// HookURLPublic says HookURL is on the configured public URL rather than
	// guessed from this request, which may be a tunnel nothing else can reach.
	HookURLPublic bool

	// HookSecret is set only on the response that issued it. It is never read
	// back, so this is the one render that can show it.
	HookSecret string

	// GitHubOn is whether the install has a GitHub App, so the source can be
	// chosen from the team's repositories rather than only pasted.
	GitHubOn bool

	// Sleep is the app's sleeping — setting, state, history — where the
	// server can put apps to sleep; nil leaves every sleep control off.
	Sleep *app.SleepStatus

	// Region is where the app lives, on an install with regions; nil on one
	// without, which draws nothing about regions at all.
	Region *AppRegionData

	// Database and Backups are a database's two extra tabs, loaded only when
	// one of them is open: each dials the database or reads its jobs. See
	// database.go.
	Database *DatabaseData
	Backups  *BackupsData
}

