// ---------------------------------------------------------------- new app

type NewAppData struct {
	Error string
	Form  NewAppForm

	// Project is the slug of the project the app goes into, and ProjectName
	// what it is called; empty is the default project.
	Project, ProjectName string

	// Source is what the person picked. Empty shows the picker instead of a
	// form: there is no sensible default, and choosing for them is how you end
	// up with a database deployed as a bare image.
	Source app.Source

	// Blueprint is the chosen source's settings, so the form can show what is
	// already decided rather than asking again.
	Blueprint app.Blueprint

	Sources []app.Blueprint

	// CanConfigureRegistry decides whether an unavailable Git source offers a
	// way out or only names who has one. The registry page is owner-only, so
	// linking a member to it would replace a dead end with a locked door.
	CanConfigureRegistry bool

	// RoomShort says the install is nearly out of room, so a deploy may be
	// refused. Said before the form is filled in rather than only after.
	RoomShort bool

	// Regions is the region field: nothing on an install with no regions.
	Regions app.RegionChoice

	// GitHubOn offers the team's GitHub repositories beside a pasted URL.
	GitHubOn bool

	// CLI is what the product's CLI is called, for the empty service, whose
	// source arrives through its up.
	CLI string
}

// NewAppForm preserves what the user typed so a validation error does not
// discard their input.
type NewAppForm struct {
	Name     string
	Image    string
	Port     string
	Replicas string
	Env      string

	// The repository, for a source that is built rather than pulled:
	// chosen from GitHub, as the picker's value, or pasted.
	GitHubRepo string
	RepoURL    string
	RepoBranch string
	RepoSubdir string

	// Region is where it goes, on an install with regions.
	Region string
}

